let _now = now() - 5h;
let _today = startofday(_now);
let _today_str = format_datetime(_today, 'yyyy-MM-dd');
let _visitors = toscalar(
    officeCam
    | where ts >= _today and ts <= _now and event_type == "PERSON_ENTERED"
    | count);
let _txns = toscalar(
    StoreRevenue
    | where rev_date == _today_str and rev_hour <= datetime_part("hour", _now)
    | summarize sum(num_transactions));
let _rate = iff(_visitors == 0, 0.0, round(todouble(_txns) / todouble(_visitors) * 100.0, 1));
print ConversionRate = strcat(tostring(_rate), "%")

let _now = now() - 5h;
let _today = startofday(_now);
let _today_str = format_datetime(_today, 'yyyy-MM-dd');
let _footfall =
    officeCam
    | where ts >= _today and ts <= _now and event_type == "PERSON_ENTERED"
    | extend h = datetime_part("hour", ts)
    | summarize Footfall = count() by h;
StoreRevenue
| where rev_date == _today_str and rev_hour <= datetime_part("hour", _now)
| join kind=leftouter _footfall on $left.rev_hour == $right.h
| project Hour = rev_hour, Revenue = revenue, Footfall = coalesce(Footfall, 0)
| order by Hour asc

let _now = now() - 5h;
let _entries =
    officeCam
    | where ts >= _now - 7d and ts <= _now and event_type == "PERSON_ENTERED"
    | summarize entry_ts = min(ts) by track_id, entry_day = startofday(ts);
let _exits =
    officeCam
    | where ts >= _now - 7d and ts <= _now and event_type == "PERSON_EXITED"
    | summarize exit_ts = max(ts) by track_id, exit_day = startofday(ts);
_entries
| join kind=inner _exits on $left.track_id == $right.track_id, $left.entry_day == $right.exit_day
| extend dwell_min = datetime_diff("minute", exit_ts, entry_ts)
| where dwell_min > 0 and dwell_min < 180
| extend Hour = datetime_part("hour", entry_ts)
| summarize AvgDwellMinutes = round(avg(todouble(dwell_min)), 1) by Hour
| order by Hour asc

